function searchEmbeddedKnowledgeBase(question) {
    if (typeof EMBEDDED_KNOWLEDGE_BASE === 'undefined' || !Array.isArray(EMBEDDED_KNOWLEDGE_BASE)) {
        return null;
    }
    const qClean = question.toLowerCase().replace(/[^\w\s\u00C0-\u1EF9]/g, ' ').trim();
    const words = qClean.split(/\s+/).filter(w => w.length > 2);
    if (words.length === 0) return null;

    let bestMatches = [];

    for (let item of EMBEDDED_KNOWLEDGE_BASE) {
        let score = 0;
        const titleLower = (item.title || '').toLowerCase();
        const contentLower = (item.content || '').toLowerCase();
        const kwList = item.keywords || [];

        // Exact phrase match
        if (titleLower.includes(qClean)) score += 50;
        if (contentLower.includes(qClean)) score += 30;

        // Word matches
        for (let w of words) {
            if (titleLower.includes(w)) score += 8;
            if (kwList.includes(w)) score += 5;
            if (contentLower.includes(w)) score += 2;
        }

        if (score > 10) {
            bestMatches.push({ item, score });
        }
    }

    bestMatches.sort((a, b) => b.score - a.score);
    return bestMatches.slice(0, 3).map(m => m.item);
}


